from decimal import Decimal, ROUND_HALF_UP
af(3,'bm41-capital-revenue','3.1','sl','Capital and revenue expenditure','capital expenditure','Spending to acquire or improve non-current assets / expected to benefit the organization over more than one accounting period.','Distinguish capital expenditure from revenue expenditure using two items in the case of {name}.',[
('Ora Milling','Ora buys a new grain mill for USD 90000 and pays USD 2400 for its routine monthly servicing. The servicing does not extend the mill’s expected useful life.', ['The mill purchase is capital expenditure.','It acquires an asset used over several years.','The USD 90000 supports future milling rather than just this month’s activity.'],['Routine servicing is revenue expenditure.','It maintains current operations without adding a long-term improvement.','The USD 2400 belongs to the current period’s operating costs.']),
('Pra Films','Pra buys editing computers for USD 18000 and pays USD 1500 for one month’s studio rent. The computers will be used for three years.', ['The computers are capital expenditure.','They provide productive capacity for three years.','The USD 18000 purchase creates non-current assets rather than only a one-month benefit.'],['Monthly rent is revenue expenditure.','It pays for use of the studio during the current month.','The USD 1500 does not acquire ownership of a lasting studio asset.']),
('Qra Boats','Qra adds a new engine costing USD 22000 to extend a boat’s useful life, and spends USD 800 on fuel for the current week’s trips.', ['The engine improvement is capital expenditure.','It extends the boat’s useful life beyond the current period.','The USD 22000 therefore provides future operating benefits.'],['Fuel is revenue expenditure.','It is consumed in providing this week’s trips.','The USD 800 supports current operations rather than a lasting asset improvement.']),
('Rra Foods','Rra builds a temperature-controlled store for USD 140000 and buys USD 6000 of disposable packaging used entirely during the month.', ['The store is capital expenditure.','It is a non-current facility used over future periods.','The USD 140000 adds long-term storage capacity.'],['Packaging consumed this month is revenue expenditure.','It supports current food sales rather than a long-term asset.','The USD 6000 is used up in the month’s activity.'])],exam='paper-2')
ef(3,'bm42-long-term-finance','3.2','sl','Long-term finance','retained profit','Profit kept within the business after distributions to owners / available as an internal source of finance for future activity.','using the proposed long-term source of finance',[
('Sra Solar','Sra needs USD 180000 for installation equipment lasting eight years. A bank offers a five-year fixed-interest loan. Sales are growing but receipts are concentrated in summer.','Loan capital preserves ownership;Sra’s founders retain control while acquiring long-lived equipment','Repayments create fixed cash obligations;winter receipts may be too low even if annual profit is positive','Use the loan only with a cash-flow forecast and seasonal repayment arrangement; equity may fit better if winter liquidity is weak.','The loan’s interest rate, security and repayment dates are unspecified.'),
('Tra Drinks','Tra has USD 70000 of retained profit in cash and wants a USD 60000 bottling machine. Suppliers are also demanding shorter credit terms.','Internal finance avoids interest and ownership dilution;Tra can acquire equipment without new lenders or shareholders','Using the cash may weaken working capital;only USD 10000 remains while suppliers demand earlier payment','Use retained funds only after protecting operating liquidity; combine a smaller cash contribution with suitable asset finance if necessary.','The minimum working-capital buffer and timing of supplier payments are unknown.'),
('Ura Learning','Ura needs finance for a new learning platform with uncertain first-year revenue. A business angel offers equity and sector expertise but wants 30% ownership.','Equity avoids fixed repayments during development;the angel’s expertise may also improve Ura’s launch decisions','Founders lose part of ownership and future returns;the angel may influence priorities through the 30% stake','Accept if expertise and patient funding justify dilution and governance terms protect the mission; compare staged funding before committing.','The angel’s control rights and the platform valuation are not given.'),
('Vra Clinics','Vra wants advanced scanners but expects technology to change quickly. Leasing would spread payments and include maintenance, although the total five-year payments exceed the cash price.','Leasing preserves launch cash and can include maintenance;Vra can use scanners while retaining funds for clinical operations','Total payments may be higher and ownership may not transfer;Vra must meet lease commitments even if demand disappoints','Lease if flexibility and maintenance are worth the premium; check upgrade and exit terms before accepting.','The equipment utilization forecast and cancellation or upgrade terms are unknown.')])
ef(3,'bm43-short-term-finance','3.2','sl','Working-capital finance','overdraft','An arrangement allowing a bank account to have a negative balance up to an agreed limit / providing flexible short-term borrowing on which interest is charged.','using the proposed short-term financing arrangement',[
('Wra Toys','Wra must buy stock in August for December sales. The bank offers an overdraft reviewed annually, and the owner proposes using it for both stock and a ten-year warehouse.','Flexible borrowing fits seasonal stock needs;December receipts could repay the temporary August deficit','A short-term facility mismatches a long-lived asset;the bank could reduce the overdraft while the warehouse remains illiquid','Use an overdraft for the forecast seasonal gap, but seek long-term finance for the warehouse.','No monthly cash-flow forecast or overdraft terms are supplied.'),
('Xra Fashion','Xra can obtain 45 days of trade credit for fabric. Its retailer normally pays after 75 days, and the supplier will stop deliveries if payment is late.','Trade credit delays the immediate cash outflow;Xra can begin production before paying for fabric','The cash gap is not eliminated;payment falls due 30 days before the retailer normally pays','Negotiate aligned terms or secure temporary bridging finance rather than assume supplier credit fully funds production.','The retailer’s payment reliability and Xra’s other cash receipts are unknown.'),
('Yra Gardens','Yra proposes invoice discounting for reliable commercial customers to cover wages. The provider advances cash quickly but charges a fee and excludes disputed invoices.','Earlier invoice cash can fund wages;Yra need not wait for commercial customers’ normal payment date','Fees reduce the margin and disputed invoices remain unfunded;the cash source may shrink precisely when service complaints rise','Use selectively for verified invoices if the wage timing benefit exceeds fees; address collection and service disputes as well.','The fee schedule and proportion of eligible invoices are not specified.'),
('Zra Foods','Zra seeks 60-day supplier credit to fund a one-off festival order. Festival organizers pay a 50% deposit, but unsold food cannot be returned and spoils quickly.','Supplier credit can match a short trading cycle;the festival deposit helps fund costs before final sales','Deferred payment does not remove demand risk;Zra still owes suppliers for spoiled unsold food','Limit the order to credible demand and use the deposit plus credit for the remaining short gap; avoid overordering simply because credit is available.','Expected attendance, spoilage and the exact supplier due date are uncertain.')])

for name,product,fixed,var,q in [('Avo Panels','insulation panels',48000,14,6000),('Bvo Baskets','woven baskets',12500,9,2500),('Cvo Kits','science kits',36000,22,4000),('Dvo Filters','filter units',72000,31,8000)]:
    total=fixed+var*q; avg=total/q
    items=[calc('a','Calculate total monthly cost.',f'Fixed cost + variable cost per unit × output = {fixed}+{var}×{q}.',f'USD {total:,.2f}.'),calc('b','Calculate average cost per unit.',f'Total cost / output = {total}/{q}.',f'USD {avg:.2f} per unit.'),explain('c','Explain why a higher output does not necessarily increase profit.',['Higher output can spread fixed cost over more units.','But producing units does not prove they can be sold.','If demand is insufficient, inventory and storage costs can rise without equivalent revenue.','The selling price and achievable sales volume are needed before concluding that profit increases.'])]
    add(3,'bm44-cost-classification','3.3','sl',f'{name}: total and average cost','Costs and revenues',f'{name} makes {product}. Monthly fixed costs are USD {fixed:,}; variable cost is USD {var} per unit. It produces {q:,} units in the month. Within this output range, fixed costs and variable cost per unit remain unchanged. Show workings and give money to two decimal places.',items,kind='data-response',check=f'Total={total}; average={avg:.8f}; multiplying average by quantity recovers total. No inference about sales or profit from output alone.')
for name,sector,price,units,fee,subs in [('Evo Media','digital design',45,800,12,350),('Fvo Fitness','fitness classes',18,2400,25,520),('Gvo Gardens','plant deliveries',32,1600,9,700),('Hvo Coding','coding courses',75,420,16,260)]:
    rev=price*units+fee*subs
    items=[calc('a','Calculate total monthly revenue from both streams.',f'{price}×{units}+{fee}×{subs}.',f'USD {rev:,.2f}.'),calc('b','Calculate subscription revenue as a percentage of total revenue. Give the answer to two decimal places.',f'({fee}×{subs})/{rev}×100.',f'{fee*subs/rev*100:.2f}%.'),explain('c','Explain one benefit and one risk of relying more on subscriptions.',['Subscriptions can make revenue more predictable.','The monthly fee creates recurring receipts rather than relying only on individual purchases.','The recurring service creates an obligation and retention risk.','If users cancel or servicing them costs too much, the subscription stream may not generate sufficient profit.'])]
    add(3,'bm45-revenue-streams','3.3','sl',f'{name}: two revenue streams','Revenue streams',f'{name} supplies {sector}. In one month it sells {units} individual services at USD {price} each and has {subs} subscriptions at USD {fee} per month. The subscriptions do not include any of the individual services counted above. All amounts are earned revenue for this month; ignore taxes and refunds. Show workings.',items,kind='data-response',check=f'Individual={price*units}; subscription={fee*subs}; total={rev}; subscription share={fee*subs/rev*100:.8f}%. Streams expressly non-overlapping.')
for name,sector,rev,cogs,exp,interest,tax in [('Ivo Textiles','textiles',480000,276000,116000,8000,16000),('Jvo Meals','prepared meals',360000,198000,102000,6000,10800),('Kvo Tools','hand tools',720000,432000,180000,12000,19200),('Lvo Books','books',250000,137500,72500,5000,7000)]:
    gp=rev-cogs; pbit=gp-exp;pat=pbit-interest-tax
    stem=f'{name} sells {sector}. Extract from its annual statement of profit or loss (USD):\n\n| Item | USD |\n|---|---:|\n| Revenue | {rev:,} |\n| Cost of sales | {cogs:,} |\n| Expenses excluding interest and tax | {exp:,} |\n| Interest | {interest:,} |\n| Tax | {tax:,} |\n\nAll figures relate to the same year. Show workings and give money to two decimal places.'
    items=[calc('a','Calculate gross profit.',f'Revenue−cost of sales={rev}−{cogs}.',f'USD {gp:,.2f}.'),calc('b','Calculate profit before interest and tax.',f'Gross profit−expenses={gp}−{exp}.',f'USD {pbit:,.2f}.'),calc('c','Calculate profit for the year after interest and tax.',f'{pbit}−{interest}−{tax}.',f'USD {pat:,.2f}.'),explain('d','Explain why this positive annual profit does not prove that every monthly cash balance was positive.',['Revenue and cash receipt can occur at different times.','Credit customers may pay after the related sales are recorded.','Asset purchases or debt repayments may also use cash without the same immediate expense.','The timing of receipts and payments requires a cash-flow forecast, not merely the annual profit total.'])]
    add(3,'bm46-profit-statement','3.4','sl',f'{name}: statement of profit or loss','Final accounts',stem,items,kind='data-response',check=f'Gross={gp}; PBIT={pbit}; after interest/tax={pat}; all stages reconcile to revenue minus listed costs. Cash and accounting profit distinguished.')
for name,sector,nca,stock,debtors,cash,cl,longdebt in [('Mvo Furniture','furniture',180000,42000,36000,12000,50000,70000),('Nvo Optics','optical lenses',260000,18000,52000,20000,60000,110000),('Ovo Toys','toys',95000,28000,16000,9000,33000,40000),('Pvo Foods','food processing',320000,60000,45000,15000,80000,150000)]:
    ca=stock+debtors+cash;equity=nca+ca-cl-longdebt;wc=ca-cl
    stem=f'{name} makes {sector}. Statement of financial position data at 31 December (USD): non-current assets {nca:,}; inventories {stock:,}; trade receivables {debtors:,}; cash {cash:,}; current liabilities {cl:,}; non-current liabilities {longdebt:,}. There are no other assets or liabilities. Show workings and give money to two decimal places.'
    items=[calc('a','Calculate total current assets.',f'{stock}+{debtors}+{cash}.',f'USD {ca:,.2f}.'),calc('b','Calculate net assets, equal to total equity in this case.',f'Total assets−total liabilities={nca}+{ca}−{cl}−{longdebt}.',f'USD {equity:,.2f}.'),calc('c','Calculate working capital.',f'Current assets−current liabilities={ca}−{cl}.',f'USD {wc:,.2f}.'),explain('d','Explain one limitation of assuming that positive working capital guarantees immediate ability to pay all debts.',['Some current assets are inventories or receivables rather than cash.','Inventories may take time to sell and customers may pay late.','The current liabilities may fall due before those assets are converted into cash.','A dated cash-flow forecast is needed to assess immediate payment ability.'])]
    add(3,'bm47-financial-position','3.4','sl',f'{name}: financial position','Final accounts',stem,items,kind='data-response',check=f'Current assets={ca}; assets-liabilities/equity={equity}; working capital={wc}. Net assets + total liabilities = total assets.')
for name,sector,r1,c1,e1,r2,c2,e2 in [('Qvo Wear','clothing',240000,144000,60000,300000,195000,66000),('Rvo Audio','speakers',400000,240000,100000,440000,250800,127600),('Svo Games','board games',180000,99000,54000,216000,129600,56160),('Tvo Fruit','fruit retail',320000,224000,64000,352000,235840,77440)]:
    g1=(r1-c1)/r1*100;g2=(r2-c2)/r2*100;pm1=(r1-c1-e1)/r1*100;pm2=(r2-c2-e2)/r2*100
    items=[calc('a','Calculate Year 2 gross profit margin.',f'({r2}−{c2})/{r2}×100.',f'{g2:.2f}%.'),calc('b','Calculate Year 2 profit margin, using profit before interest and tax.',f'({r2}−{c2}−{e2})/{r2}×100.',f'{pm2:.2f}%.'),explain('c','Explain why higher revenue alone is insufficient evidence that profitability improved.',['Profitability relates profit to revenue, not simply the total revenue received.',f'Gross margin changes from {g1:.2f}% in Year 1 to {g2:.2f}% in Year 2.',f'Profit margin changes from {pm1:.2f}% to {pm2:.2f}%, so the cost structure matters.','Higher sales may be accompanied by higher cost of sales or operating expenses, changing the share retained as profit.'])]
    add(3,'bm48-profitability-margins','3.5','sl',f'{name}: profitability comparison','Profitability ratios',f'{name} sells {sector}. Annual figures in USD:\n\n| Item | Year 1 | Year 2 |\n|---|---:|---:|\n| Revenue | {r1:,} | {r2:,} |\n| Cost of sales | {c1:,} | {c2:,} |\n| Expenses excluding interest and tax | {e1:,} | {e2:,} |\n\nUse profit before interest and tax for profit margin. Give percentages to two decimal places and show workings.',items,kind='data-response',check=f'GPM1={g1};GPM2={g2};PM1={pm1};PM2={pm2}. Ratio conclusions distinguish revenue growth from profitability.')
for name,sector,pbit,eq,debt,newp,newcap in [('Uvo Sensors','sensors',78000,300000,90000,90000,500000),('Vvo Schools','education',54000,220000,80000,72000,360000),('Wvo Farms','farming',96000,380000,100000,102000,600000),('Xvo Clinics','diagnostics',126000,500000,200000,144000,800000)]:
    old=pbit/(eq+debt)*100;new=newp/newcap*100
    items=[calc('a','Calculate current ROCE using equity plus non-current liabilities as capital employed.',f'{pbit}/({eq}+{debt})×100.',f'{old:.2f}%.'),calc('b','Calculate forecast ROCE after expansion.',f'{newp}/{newcap}×100.',f'{new:.2f}%.'),ten('c',f'Using the financial data, recommend whether {name} should undertake the expansion.',name,'the proposed expansion',f'Annual profit before interest and tax rises from USD {pbit:,} to USD {newp:,}',f'Capital employed rises and ROCE changes from {old:.2f}% to {new:.2f}%; extra profit must justify the extra investment',f'Compare forecast ROCE with the cost and risk of capital and strategic benefits; higher absolute profit alone does not settle the choice.','The forecast’s reliability, cost of capital, cash-flow timing and non-financial benefits are not given.')]
    add(3,'bm49-roce','3.5','sl',f'{name}: returns on expansion','Return on capital employed',f'{name} supplies {sector}. Current annual profit before interest and tax is USD {pbit:,}; equity is USD {eq:,}; non-current liabilities are USD {debt:,}. An expansion would produce forecast annual profit before interest and tax of USD {newp:,} with total capital employed of USD {newcap:,}. These are comparable full-year estimates. Use the stated capital-employed bases without averaging. Show workings; percentages to two decimals.',items,kind='data-response',check=f'CurrentCE={eq+debt};ROCE={old:.8f}%;forecast={new:.8f}%. Forecast not treated as guaranteed or compared solely on absolute profit.')
for name,sector,stock,receiv,cash,cl,pay in [('Yvo Cycles','bicycles',45000,30000,15000,60000,12000),('Zvo Glass','glassware',70000,40000,20000,80000,16000),('Awa Books','books',28000,22000,10000,30000,6000),('Bwa Foods','groceries',54000,16000,10000,50000,10000)]:
    ca=stock+receiv+cash;cur=ca/cl;quick=(ca-stock)/cl;new=(ca-pay)/(cl-pay)
    items=[calc('a','Calculate the current ratio and acid-test ratio.',f'Current={ca}/{cl}; acid test=({ca}−{stock})/{cl}.',f'Current={Decimal(str(cur)).quantize(Decimal("0.01"),rounding=ROUND_HALF_UP)}:1; acid test={Decimal(str(quick)).quantize(Decimal("0.01"),rounding=ROUND_HALF_UP)}:1. Award the method mark for correct ratio setups and the accuracy mark for both correct ratios.'),calc('b',f'Calculate the current ratio after paying USD {pay:,} of current liabilities with cash.',f'({ca}−{pay})/({cl}−{pay}).',f'{Decimal(str(new)).quantize(Decimal("0.01"),rounding=ROUND_HALF_UP)}:1.'),explain('c','Explain why a higher current ratio after the payment does not mean that cash increased.',['The payment reduces both cash and current liabilities.','Because the initial ratio exceeds one, reducing both by the same amount increases the ratio.','Cash is nevertheless lower after paying the liability.','Liquidity assessment must therefore consider cash timing and asset composition as well as the ratio.'])]
    add(3,'bm50-liquidity','3.5','sl',f'{name}: liquidity and payment','Liquidity ratios',f'{name} sells {sector}. At month-end, inventories are USD {stock:,}, receivables USD {receiv:,}, cash USD {cash:,} and current liabilities USD {cl:,}. There are no other current assets. A payment of USD {pay:,} from cash would reduce current liabilities by exactly that amount. No other item changes. Show workings and express ratios to two decimal places.',items,kind='data-response',check=f'CA={ca};current={cur};acid={quick};postpayment={new};cashafter={cash-pay}. Paying cash cannot be claimed to raise cash; positive balance verified.')
for name,sector,opening,receipts,payments,purchase in [('Cwa Toys','toy retail',22000,[30000,52000,40000],[38000,36000,35000],15000),('Dwa Tours','tours',18000,[20000,46000,28000],[27000,32000,26000],12000),('Ewa Seeds','seed supply',26000,[24000,58000,36000],[41000,33000,30000],18000),('Fwa Prints','printing',15000,[32000,29000,48000],[28000,37000,31000],10000)]:
    bal=[];b=opening
    for r,p in zip(receipts,payments):b+=r-p;bal.append(b)
    post=[x-purchase for x in bal]
    table='\n\n| Month | 1 | 2 | 3 |\n|---|---:|---:|---:|\n| Cash receipts, USD | '+' | '.join(f'{x:,}' for x in receipts)+' |\n| Operating cash payments, USD | '+' | '.join(f'{x:,}' for x in payments)+' |\n\n'
    items=[calc('a','Calculate the closing cash balances in months 1 and 2 before the machine purchase.',f'Month1={opening}+{receipts[0]}−{payments[0]}; month2=month1+{receipts[1]}−{payments[1]}.',f'Month1 USD {bal[0]:,.2f}; month2 USD {bal[1]:,.2f}. Method mark for sequential balances; accuracy mark for both.'),calc('b','Calculate the lowest closing cash balance over the three months if the machine is purchased at the start of month 1.',f'Deduct USD {purchase:,} from every baseline closing balance: '+', '.join(str(x) for x in post)+'.',f'USD {min(post):,.2f}.'),ten('c',f'Recommend whether {name} should buy the machine at the start of month 1.',name,'the immediate machine purchase',f'The machine may provide future productive capacity, and the forecast closing balances after purchase are {post}',f'The lowest forecast balance is USD {min(post):,}; a negative balance requires finance and a small positive balance leaves little protection', 'Buy only if a dated forecast and confirmed finance protect essential payments; delaying until stronger receipts may reduce liquidity risk.','The forecast contains monthly closing balances but not intra-month payment dates, forecast accuracy or measured machine benefits.')]
    add(3,'bm51-cash-forecast','3.7','sl',f'{name}: cash-flow forecast','Cash flow',f'{name} supplies {sector}. Opening cash before month 1 is USD {opening:,}. The following are cash amounts, not accounting revenue or expense.'+table+f'A machine costing USD {purchase:,} could be bought for cash at the start of month 1. It has no effect on the listed operating receipts or payments during these three months. There are no other cash flows and no existing overdraft. Show workings.',items,kind='data-response',check=f'Baseline sequential balances={bal}; postmachine={post}; minimum={min(post)}. The one-off purchase is subtracted once, not once each month.')
for name,project,cost,flows in [('Gwa Fibre','a fibre-processing machine',90000,[24000,30000,42000,36000]),('Hwa Care','a mobile diagnostic van',120000,[30000,42000,60000,48000]),('Iwa Foods','a cold store',76000,[18000,25000,33000,30000]),('Jwa Glass','a polishing machine',64000,[16000,20000,36000,26000])]:
    cum=0;pb=None
    for year,f in enumerate(flows,1):
        if cum+f>=cost:pb=(year-1)+(cost-cum)/f;break
        cum+=f
    items=[calc('a','Calculate the payback period in years, to two decimal places.',f'After {year-1} full years cumulative net inflow is USD {cum:,}; remaining USD {cost-cum:,} / year-{year} inflow USD {f:,}.',f'{pb:.2f} years.'),explain('b','Explain one benefit and one limitation of using payback for this investment.',['Payback indicates how quickly the initial cash outlay is recovered.','This is relevant where the business needs to restore liquidity or faces uncertain later demand.','Payback ignores net cash inflows after the recovery date.','It can therefore favor a faster-recovering project even when another has greater total returns.']),ten('c',f'Recommend whether {name} should accept the project if its target payback is 3.00 years.',name,'the investment',f'Payback is {pb:.2f} years against the 3.00-year target',f'The target ignores later returns and non-financial effects; the four-year net inflow total is USD {sum(flows):,} before the initial cost',f'On the stated payback rule, {"accept" if pb<=3 else "reject or review"}; a final decision should also consider overall return, finance and strategic benefits.','The reliability of forecast inflows, alternative projects and the business’s liquidity constraints are not specified.')]
    add(3,'bm52-payback','3.8','sl',f'{name}: payback period','Investment appraisal',f'{name} considers {project}. It costs USD {cost:,} at time zero and generates annual net cash inflows of USD '+', '.join(f'{x:,}' for x in flows)+f' in years 1–4 respectively. The project ends after year 4 with no residual value. Assume inflows accrue evenly within each year for fractional payback. The target payback is 3.00 years. Ignore discounting and tax. Show workings.',items,kind='data-response',check=f'Independent cumulative crossing inyear{year}; priorcum={cum}; residual={cost-cum}; payback={pb:.8f}; totalnetafterinvestment={sum(flows)-cost}.')
for name,project,cost,years,annual,target in [('Kwa Labs','a testing line',100000,5,30000,12),('Lwa Rooms','a booking platform',60000,4,21000,15),('Mwa Mills','a grain dryer',150000,6,41000,10),('Nwa Farms','an irrigation system',80000,5,23000,9)]:
    profit=(annual*years-cost)/years;arr=profit/cost*100
    items=[calc('a','Calculate average annual accounting profit over the project life.',f'({annual}×{years}−{cost})/{years}.',f'USD {profit:,.2f} per year.'),calc('b','Calculate ARR using the original capital cost as the denominator.',f'{profit}/{cost}×100.',f'{arr:.2f}%.'),ten('c',f'Recommend whether {name} should invest, considering the ARR target and limitations of the information.',name,'the proposed investment',f'ARR is {arr:.2f}% compared with the {target:.2f}% target',f'ARR averages profit and ignores when cash arrives; the original USD {cost:,} must still be financed',f'The ARR rule suggests {"acceptance" if arr>=target else "rejection or revision"}, but compare cash-flow timing, financing and non-financial benefits before committing.','Forecast cash inflows are assumed constant and no risk estimate, financing cost or alternative use of capital is supplied.')]
    add(3,'bm53-arr','3.8','sl',f'{name}: average rate of return','Investment appraisal',f'{name} considers {project}. Initial cost is USD {cost:,}; life is {years} years; forecast net operating cash inflow is USD {annual:,} each year; residual value is zero. For this ARR exercise, total accounting profit over the life equals total net cash inflows minus initial cost. Use original capital cost, not average investment, as the ARR denominator. Target ARR is {target}%. Ignore tax and discounting; show workings and round money and percentages to two decimal places.',items,kind='data-response',check=f'Totalprofit={annual*years-cost}; annualprofit={profit}; ARR={arr:.8f}%; denominator initialcapital={cost}, not halfcost.')
for name,asset,cost,residual,life,age in [('Owa Foods','a packaging line',96000,16000,5,2),('Pwa Transport','a delivery van',54000,9000,6,3),('Qwa Films','camera equipment',38000,8000,5,1),('Rwa Furniture','a cutting machine',125000,25000,8,4)]:
    dep=(cost-residual)/life;book=cost-age*dep
    items=[calc('a','Calculate annual straight-line depreciation.',f'({cost}−{residual})/{life}.',f'USD {dep:,.2f} per year.'),calc('b',f'Calculate carrying value after {age} complete years.',f'{cost}−{age}×{dep}.',f'USD {book:,.2f}.'),explain('c','Explain why depreciation reduces reported profit but is not itself a cash payment in the year.',['Depreciation allocates the depreciable cost to accounting periods.','The annual expense reduces profit for use of the asset during the year.','Cash was paid when the asset was bought, subject to the stated cash purchase.','Recording annual depreciation does not repeat that original cash outflow.'])]
    add(3,'bm54-straight-line','3.4','ahl',f'{name}: straight-line depreciation','Depreciation',f'{name} purchases {asset} for cash at USD {cost:,}. Expected residual value is USD {residual:,}, with a {life}-year useful life. It uses straight-line depreciation, charging a full year for each complete year of use. Assume no impairment, revaluation or change in estimates. Show workings and give money to two decimal places.',items,kind='data-response',check=f'Annualdep={dep}; carryingafter{age}={book}; depreciablebase={cost-residual}; carryingvalue at life end={cost-life*dep}=residual.')
for name,asset,cost,residual,capacity,output in [('Swa Press','a printing press',180000,30000,1500000,240000),('Twa Metal','a stamping machine',112000,12000,800000,140000),('Uwa Clay','a tile press',76000,6000,700000,175000),('Vwa Plastics','a moulding line',250000,50000,2000000,320000)]:
    per=(cost-residual)/capacity;dep=per*output
    items=[calc('a','Calculate depreciation per unit of expected lifetime output.',f'({cost}−{residual})/{capacity}.',f'USD {per:.4f} per unit.'),calc('b','Calculate depreciation for Year 1 using units of production.',f'{output}×{per}.',f'USD {dep:,.2f}.'),explain('c','Explain one advantage and one limitation of units-of-production depreciation for this asset.',['The charge follows usage.','A year with more units receives more of the asset cost where wear is output-related.','Expected lifetime output is uncertain.','An inaccurate capacity estimate may misstate depreciation per unit and the reported annual profit.'])]
    add(3,'bm55-units-production','3.4','ahl',f'{name}: usage-based depreciation','Depreciation',f'{name} buys {asset} for USD {cost:,}, expects residual value USD {residual:,} and total lifetime output {capacity:,} units. Year 1 output is {output:,} units. Assume wear is related to output, no time-based depreciation component and no change in estimates. Use the units-of-production method. Show workings; per-unit depreciation to four decimal places, final money to two.',items,kind='data-response',check=f'Dep/unit={per}; Year1dep={dep}; remainingvalue={cost-dep}; fullcapacity depreciation={per*capacity}=cost-residual.')
