    table='\n\n| Year | Net cash inflow, USD | Discount factor |\n|---|---:|---:|\n'+'\n'.join(f'| {j+1} | {flows[j]:,} | {factors[j]:.4f} |' for j in range(3))+'\n\n'
    items=[calc('a','Calculate the present value of all three future net cash inflows using the supplied factors.', ' + '.join(f'{a}×{b:.4f}' for a,b in zip(flows,factors))+'.',f'USD {sum(pv):,.2f}.'),calc('b','Calculate the project’s net present value.',f'{sum(pv):.2f}−{cost}.',f'USD {npv:,.2f}.'),ten('c',f'Recommend whether {name} should accept this project, using NPV and other relevant considerations.',name,'the proposed project',f'NPV is USD {npv:,.2f} at the {rate*100:g}% rate; a positive NPV indicates value above the required return on the stated estimates',f'NPV depends on forecast inflows and the discount rate; cash finance of USD {cost:,} is needed now',f'The NPV rule suggests {"acceptance" if npv>0 else "rejection"} on the given estimates; test downside inflows and operational feasibility before committing.','No sensitivity estimates, funding terms or non-financial impacts are supplied.')]
